  tools.exec_command({cmd:"python -B - <<'PY'
import json,runpy,collections,statistics
score=runpy.run_path('verl/utils/reward_score/math_dapo.py')['compute_score']
for file in ['outputs/frozen_eval/0.jsonl','outputs/frozen_eval/150.jsonl','outputs/rollouts/1.jsonl','outputs/rollouts/75.jsonl','outputs/rollouts/150.jsonl']:
 rows=[json.loads(l) for l in open(file)]; grouped=collections.defaultdict(list)
 bad=[]
 for i,r in enumerate(rows):
  computed=float(score(r['output'],str(r['gts']),strict_box_verify=False)['acc'])
  if any(r[k]!=computed for k in ['score','acc','oracle_acc']): bad.append(i)
  grouped[r['data_source']].append(r)
 print(file,'rows',len(rows),'score_mismatches',len(bad),'buckets',dict(collections.Counter(r['context_bucket'] for r in rows)))
 for source,rs in grouped.items():
  probs=collections.defaultdict(list)
  for r in rs: probs[r['problem_id']].append(r)
  counts=collections.Counter(len(g) for g in probs.values())
  print(source,'correct',sum(r['score'] for r in rs),'total',len(rs),'accuracy',statistics.mean(r['score'] for r in rs),'unique_problems',len(probs),'samples_per_problem_hist',dict(counts),'problems_with_success',sum(any(x['score'] for x in g) for g in probs.values()),'output_chars_mean',round(statistics.mean(len(r['output']) for r in rs),2))
  if 'rollouts' in file:
   blocks=[rs[i:i+8] for i in range(0,len(rs),8)]
   print('8-draw groups','valid_input_grouping',all(len({r['input'] for r in g})==1 for g in blocks),'all_zero',sum(sum(r['score'] for r in g)==0 for g in blocks),'mixed',sum(0<sum(r['score'] for r in g)<8 for g in blocks),'all_one',sum(sum(r['score'] for r in g)==8 for g in blocks))
PY","max_output_tokens":3000}),
  tools.exec_command({cmd:"rg -n 'VLLM_SLEEP_LEVEL|_check_vllm_version_for_sleep_level|local_path|update_weights|wake_up|resume' verl/workers/rollout/vllm_rollout/vllm_rollout_spmd.py verl/workers/fsdp_workers.py verl/workers/config/model.py verl/experimental/agent_loop/agent_loop.py verl/workers/rollout/replica.py
sed -n '220,294p' verl/utils/reward_score/math_dapo.py
sed -n '1020,1210p' verl/trainer/ppo/ray_trainer.py","max_output_tokens":7500}),
  tools.exec_command({cmd:"python -B - <<'PY'
import importlib.util
for m in ['pyarrow','tokenizers','transformers','omegaconf','yaml']: print(m,importlib.util.find_spec(m) is not None)
